package org.kairosdb.temporal;

import io.grpc.stub.StreamObserver;
import io.temporal.api.workflowservice.v1.*;

public interface RoutingService
{
	//Service in charge of keeping track of other instances and calls to the other services based on partition ownership.

	boolean routeStartWorkflowExecution(StartWorkflowExecutionRequest request, StreamObserver<StartWorkflowExecutionResponse> responseObserver);
	boolean routePollWorkflowTaskQueue(PollWorkflowTaskQueueRequest request, StreamObserver<PollWorkflowTaskQueueResponse> responseObserver);
	boolean routeRespondWorkflowTaskCompleted(RespondWorkflowTaskCompletedRequest request, StreamObserver<RespondWorkflowTaskCompletedResponse> responseObserver);
	boolean routeRespondWorkflowTaskFailed(RespondWorkflowTaskFailedRequest request, StreamObserver<RespondWorkflowTaskFailedResponse> responseObserver);
	boolean routePollActivityTaskQueue(PollActivityTaskQueueRequest request, StreamObserver<PollActivityTaskQueueResponse> responseObserver);
	boolean routeRecordActivityTaskHeartbeat(RecordActivityTaskHeartbeatRequest request, StreamObserver<RecordActivityTaskHeartbeatResponse> responseObserver);
	boolean routeRecordActivityTaskHeartbeatById(RecordActivityTaskHeartbeatByIdRequest request, StreamObserver<RecordActivityTaskHeartbeatByIdResponse> responseObserver);
	boolean routeRespondActivityTaskCompleted(RespondActivityTaskCompletedRequest request, StreamObserver<RespondActivityTaskCompletedResponse> responseObserver);
	boolean routeRespondActivityTaskCompletedById(RespondActivityTaskCompletedByIdRequest request, StreamObserver<RespondActivityTaskCompletedByIdResponse> responseObserver);
	boolean routeRespondActivityTaskFailed(RespondActivityTaskFailedRequest request, StreamObserver<RespondActivityTaskFailedResponse> responseObserver);
	boolean routeRespondActivityTaskFailedById(RespondActivityTaskFailedByIdRequest request, StreamObserver<RespondActivityTaskFailedByIdResponse> responseObserver);
	boolean routeRespondActivityTaskCanceled(RespondActivityTaskCanceledRequest request, StreamObserver<RespondActivityTaskCanceledResponse> responseObserver);
	boolean routeRespondActivityTaskCanceledById(RespondActivityTaskCanceledByIdRequest request, StreamObserver<RespondActivityTaskCanceledByIdResponse> responseObserver);
	boolean routeRequestCancelWorkflowExecution(RequestCancelWorkflowExecutionRequest request, StreamObserver<RequestCancelWorkflowExecutionResponse> responseObserver);
	boolean routeSignalWorkflowExecution(SignalWorkflowExecutionRequest request, StreamObserver<SignalWorkflowExecutionResponse> responseObserver);
	boolean routeSignalWithStartWorkflowExecution(SignalWithStartWorkflowExecutionRequest request, StreamObserver<SignalWithStartWorkflowExecutionResponse> responseObserver);
	boolean routeResetWorkflowExecution(ResetWorkflowExecutionRequest request, StreamObserver<ResetWorkflowExecutionResponse> responseObserver);
	boolean routeTerminateWorkflowExecution(TerminateWorkflowExecutionRequest request, StreamObserver<TerminateWorkflowExecutionResponse> responseObserver);
	boolean routeDeleteWorkflowExecution(DeleteWorkflowExecutionRequest request, StreamObserver<DeleteWorkflowExecutionResponse> responseObserver);
}
